# Ryley Swimming Dashboard - interactive meet-based result entry
# Run from repository root: source('scripts/enter_results.R')
root <- if (dir.exists('data')) '.' else '..'
data_dir <- file.path(root, 'data')
dir.create(data_dir, recursive=TRUE, showWarnings=FALSE)
paths <- file.path(data_dir, c('swimmers.csv','meets.csv','results.csv'))
headers <- list(c('swimmer_id','name'), c('meet_id','meet_name','meet_date','course'), c('result_id','meet_id','swimmer_id','event','time_seconds','status'))
for (i in seq_along(paths)) if (!file.exists(paths[i])) write.table(as.data.frame(setNames(replicate(length(headers[[i]]), character(0), simplify=FALSE),headers[[i]])),paths[i],sep=',',row.names=FALSE,col.names=TRUE)
load_csv <- function(n) read.csv(paths[n],stringsAsFactors=FALSE,colClasses='character',check.names=FALSE)
ask <- function(prompt) trimws(readline(prompt))
new_id <- function(prefix, values) { n <- 1L; while(sprintf('%s%05d',prefix,n) %in% values) n <- n+1L; sprintf('%s%05d',prefix,n) }
choose <- function(items, label) { cat(paste0(seq_along(items),'. ',items,'\n'),sep=''); repeat { i <- suppressWarnings(as.integer(ask(paste0(label,' number (or 0 to cancel): ')))); if(!is.na(i) && i>=0 && i<=length(items)) return(i); cat('Choose a listed number.\n') } }
parse_time <- function(x) { x <- trimws(x); if(grepl('^[0-9]+:[0-5][0-9]\\.[0-9]{1,2}$',x)) {p<-strsplit(x,':',fixed=TRUE)[[1]]; return(as.numeric(p[1])*60+as.numeric(p[2]))}; if(grepl('^[0-9]+\\.[0-9]{1,2}$',x)) return(as.numeric(x)); NA_real_ }
add_swimmer <- function() { nm <- ask('Swimmer full name: '); if(!nzchar(nm)) return(invisible(NULL)); s<-load_csv(1); if(any(tolower(s$name)==tolower(nm))) {cat('A swimmer with that name exists; select the existing swimmer.\n'); return(invisible(NULL))}; id<-new_id('S',s$swimmer_id); write.table(data.frame(swimmer_id=id,name=nm,group=ask('Training group (AG1/AG2): ')),paths[1],sep=',',row.names=FALSE,col.names=FALSE,append=TRUE); cat('Added ',nm,' (',id,')\n',sep='') }
add_meet <- function() { nm<-ask('Meet name: '); if(!nzchar(nm)) return(invisible(NULL)); repeat { dt<-ask('Meet date (YYYY-MM-DD): '); if(grepl('^[0-9]{4}-[0-9]{2}-[0-9]{2}$',dt) && !is.na(as.Date(dt,format='%Y-%m-%d')) && format(as.Date(dt),'%Y-%m-%d')==dt) break; cat('Invalid date.\n') }; c<-choose(c('SCM (25m)','LCM (50m)'), 'Course'); if(c==0) return(invisible(NULL)); m<-load_csv(2); id<-new_id('M',m$meet_id); write.table(data.frame(meet_id=id,meet_name=nm,meet_date=dt,course=c('SCM','LCM')[c]),paths[2],sep=',',row.names=FALSE,col.names=FALSE,append=TRUE); cat('Added meet ',id,'\n',sep='') }
events <- c('50m Freestyle','100m Freestyle','200m Freestyle','400m Freestyle','800m Freestyle','1500m Freestyle','50m Backstroke','100m Backstroke','200m Backstroke','50m Breaststroke','100m Breaststroke','200m Breaststroke','50m Butterfly','100m Butterfly','200m Butterfly','100m Individual Medley','200m Individual Medley','400m Individual Medley')
add_results <- function() { m<-load_csv(2); s<-load_csv(1); if(!nrow(m)||!nrow(s)){cat('Add a meet and swimmer first.\n');return(invisible(NULL))}; mi<-choose(paste(m$meet_name,m$meet_date,m$course,sep=' | '),'Meet');if(mi==0)return(invisible(NULL)); repeat {s<-load_csv(1); si<-choose(s$name,'Swimmer');if(si==0)break; ei<-choose(events,'Event');if(ei==0)next; st<-choose(c('Official time','DQ','DNS','DNF'),'Status');if(st==0)next; status<-c('OK','DQ','DNS','DNF')[st]; secs<-'';if(status=='OK'){repeat {raw<-ask('Time (e.g. 1:09.84 or 29.55): '); value<-parse_time(raw);if(!is.na(value)&&value>0){secs<-sprintf('%.2f',value);break};cat('Invalid time.\n')}}; r<-load_csv(3); if(status=='OK' && nrow(r) && any(r$meet_id==m$meet_id[mi]&r$swimmer_id==s$swimmer_id[si]&r$event==events[ei]&r$time_seconds==secs& r$status=='OK')) {cat('Possible duplicate result; not saved.\n');next}; id<-new_id('R',r$result_id); write.table(data.frame(result_id=id,meet_id=m$meet_id[mi],swimmer_id=s$swimmer_id[si],event=events[ei],time_seconds=secs,status=status),paths[3],sep=',',row.names=FALSE,col.names=FALSE,append=TRUE);cat('Saved ',id,'. Select another swimmer, or 0 to finish.\n',sep='') } }
cat('\nRYLEY SWIMMING DASHBOARD | DATA ENTRY\n');repeat { opt<-choose(c('Add swimmer','Add meet','Enter results for a meet','Exit'),'Action');if(opt==0||opt==4)break;if(opt==1)add_swimmer();if(opt==2)add_meet();if(opt==3)add_results() }
